package com.skyclone.mod.garden;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;

import java.io.Reader;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;

/**
 * Every data table of the garden, read from {@code data/garden/*.json} (generated by
 * {@code tools/gen/garden/gen_garden.py}). Pure Java + Gson, so the unit tests load the very same
 * files the server does.
 */
public final class GardenTables {

    // ---- garden.json ------------------------------------------------------------------------

    public static final class Crop {
        public String key, name, color, item, extraItem, enchanted, pest;
        public int level, baseMin, baseMax, personalBest;
        public double xp, organic;
        public List<String> blocks = new ArrayList<>();
        public long[] milestones = new long[0];
        public String display() { return (color == null ? "&e" : color) + name; }
    }

    public static final class Plot { public String id, group; public int number, col, row; }

    public static final class Cost { public String item; public int amount; }

    public static final class PlotGroup { public String id, name; public int level; public List<Cost> costs = new ArrayList<>(); }

    public static final class CropUpgrades { public int[] copper = new int[0]; public int[] levels = new int[0]; public int fortunePerTier = 5; }

    public static final class CompTier { public double value; public int copper; public Map<String, Integer> items = new LinkedHashMap<>(); }

    public static final class CompUpgrade { public String id, name, desc; public int level; public List<CompTier> tiers = new ArrayList<>(); }

    public static final class ComposterTable {
        public int intervalSeconds = 600;
        public double organicPer = 4000, fuelPer = 2000, organicCap = 40000, fuelCap = 100000;
        public List<CompUpgrade> upgrades = new ArrayList<>();
    }

    public static final class BarnSkin { public String id, name, icon, source; }

    public static final class Pest {
        public String id, name, mob;
        public int level;
        public List<String> crops = new ArrayList<>(), attractants = new ArrayList<>(), signature = new ArrayList<>();
        /** Guaranteed crop drop: {@code cropBase + fortune / cropScale} enchanted crops (lane 9, G1). */
        public double cropBase, cropScale;
        /** The pest's rare crop ("RANDOM" for the Field Mouse) and its chance (G2). */
        public String rareCrop;
        public double rareChance;
        /** Farming XP multiple of {@code garden.pest-farming-xp} (Field Mouse 4: 6,000 XP). */
        public double xpMult = 1;
        /** Only spawns at night (the Firefly, G8). */
        public boolean nightOnly;
    }

    public static final class Vacuum { public String id; public double range, damage, bpc; }

    public static final class Sprayer { public String id; public int minutes, uses = 1; public double bpc, mult; }

    public static final class Trap { public String id; public int capacity; public double mouseMult; }

    public static final class PestTable {
        public List<Pest> pests = new ArrayList<>();
        public int[][] penalty = new int[0][];
        public List<Vacuum> vacuums = new ArrayList<>();
        public List<Sprayer> sprayers = new ArrayList<>();
        public List<Trap> traps = new ArrayList<>();
        public List<String> universal = new ArrayList<>();
        /** Crop key -> the pest-drop row of that crop's pest (the Field Mouse's random crop uses it). */
        public Map<String, CropRow> cropRows = new LinkedHashMap<>();
        /** Every pest rare crop id (the Field Mouse rolls one of them). */
        public List<String> rareCrops = new ArrayList<>();
    }

    public static final class CropRow { public double base, scale; }

    /** Pesthunter Phillip's shop entry, paid in Pests. {@code item} "skin:&lt;id&gt;" is a barn skin unlock. */
    public static final class PestShopEntry {
        public String item;
        public int pests;
        public Map<String, Integer> tradeIn = new LinkedHashMap<>();
    }

    public static final class PestBonus { public double perPest = 5; public int maxPests = 40; public int minutes = 30; }

    public static final class ChipRules {
        public List<String> rarities = new ArrayList<>();
        public int[] chipsFor = {1, 5, 21}, caps = {10, 15, 20};
        public long[] sowdustCost = new long[0];
    }

    public static final class Sowdust {
        public List<String> halved = new ArrayList<>();
        public Map<String, Double> greenhouseMult = new HashMap<>();
        public double earthyPct = 5;
    }

    public static final class GreenhouseSquash { public String set = "CROPIE_", item = "SQUASH"; public double[] pct = new double[0]; }

    public static final class Chip {
        public String kind, name;
        /** Per level at Rare (the item's lore number). */
        public double per;
        /** Per level at Rare / Epic / Legendary (wiki Garden Chips). */
        public double[] perRarity = new double[0];
        public double perAt(int rarity) {
            if (perRarity == null || perRarity.length == 0) return per;
            return perRarity[Math.max(0, Math.min(perRarity.length - 1, rarity))];
        }
    }

    public static final class Garden {
        public long[] levels = new long[0];
        public List<Crop> crops = new ArrayList<>();
        public int plotSize = 96;
        public List<Plot> plots = new ArrayList<>();
        public List<PlotGroup> plotGroups = new ArrayList<>();
        public CropUpgrades cropUpgrades = new CropUpgrades();
        public ComposterTable composter = new ComposterTable();
        public Map<String, Double> organic = new HashMap<>();
        public Map<String, Double> fuel = new HashMap<>();
        public int[] uniqueVisitorMilestones = new int[0];
        public int[] acceptedMilestones = new int[0];
        public List<BarnSkin> barnSkins = new ArrayList<>();
        public PestTable pests = new PestTable();
        public Map<String, String> vinyls = new LinkedHashMap<>();
        public Map<String, Chip> chips = new LinkedHashMap<>();
        public ChipRules chipRules = new ChipRules();
        public List<PestShopEntry> pesthunterShop = new ArrayList<>();
        public PestBonus pesthunterBonus = new PestBonus();
        public Sowdust sowdust = new Sowdust();
        public GreenhouseSquash greenhouseSquash = new GreenhouseSquash();
    }

    // ---- visitors.json ----------------------------------------------------------------------

    public static final class Visitor {
        public String id, name, rarity, entity, requirement, home;
        public int level;
        public List<String> wants = new ArrayList<>();
    }

    public static final class Bonus { public String item, minRarity; public double chance; public boolean once; public int minLevel; }

    public static final class BonusTable {
        public List<Bonus> global = new ArrayList<>();
        public Map<String, List<Bonus>> special = new HashMap<>();
    }

    public static final class RarityTune { public int weight, gardenXp, copperMin, copperMax, bits; public double size; }

    public static final class VisitorsFile {
        public List<Visitor> visitors = new ArrayList<>();
        public BonusTable bonus = new BonusTable();
        public Map<String, RarityTune> rarities = new HashMap<>();
    }

    // ---- greenhouse.json --------------------------------------------------------------------

    public static final class GhCrop { public String crop; public int yield, cycles; public List<String> effects = new ArrayList<>(); }

    public static final class Effect { public String name, desc, kind; public double value; }

    public static final class Mutation {
        public String id, name, rarity, material;
        public List<String> needs = new ArrayList<>();
        public double chance, vine;
        public int cycles;
        /** First-time Crop Analyzer Copper. */
        public int copper = 250;
    }

    public static final class AnalyzerReward { public double fortune = 5, cropGrowth = 10; public int skyblockXp = 15; public String firstItem; }

    public static final class GreenhouseTable {
        public int baseStageSeconds = 14400, minStageSeconds = 6063, size = 5, xpPerHarvest = 320, plantCost = 64, waterMax = 10;
        public int[] waterPerStage = {2, 3};
        public int[] analyzerLevels = new int[0];
        public AnalyzerReward analyzerReward = new AnalyzerReward();
        public List<GhCrop> crops = new ArrayList<>();
        public Map<String, Effect> effects = new HashMap<>();
        public List<Mutation> mutations = new ArrayList<>();
        public List<Bonus> bounty = new ArrayList<>();
    }

    // ---- skymart.json -----------------------------------------------------------------------

    public static final class ShopEntry {
        public String item, currency, category;
        public double price;
        public int level;
        public Map<String, Integer> needs = new LinkedHashMap<>();
    }

    // =========================================================================================

    public Garden garden;
    public VisitorsFile visitors;
    public GreenhouseTable greenhouse;
    public List<ShopEntry> shop;

    private final Map<String, Crop> cropByKey = new LinkedHashMap<>();
    private final Map<String, Crop> cropByItem = new HashMap<>();
    private final Map<String, Crop> cropByBlock = new HashMap<>();
    private final Map<String, Plot> plotById = new LinkedHashMap<>();
    private final Plot[][] plotAt = new Plot[5][5];
    private final Map<String, PlotGroup> groupById = new HashMap<>();
    private final Map<String, Pest> pestById = new LinkedHashMap<>();
    private final Map<String, Visitor> visitorById = new LinkedHashMap<>();
    private final Map<String, Mutation> mutationById = new LinkedHashMap<>();
    private final Map<String, GhCrop> ghCropByKey = new LinkedHashMap<>();

    /** Load from a resolver of "garden.json" etc. to a Reader. */
    public static GardenTables load(Function<String, Reader> open) {
        Gson gson = new Gson();
        GardenTables t = new GardenTables();
        t.garden = gson.fromJson(open.apply("garden.json"), Garden.class);
        t.visitors = gson.fromJson(open.apply("visitors.json"), VisitorsFile.class);
        t.greenhouse = gson.fromJson(open.apply("greenhouse.json"), GreenhouseTable.class);
        t.shop = gson.fromJson(open.apply("skymart.json"), new TypeToken<List<ShopEntry>>() {}.getType());
        if (t.shop == null) t.shop = new ArrayList<>();
        t.index();
        return t;
    }

    private void index() {
        for (Crop c : garden.crops) {
            cropByKey.put(c.key, c);
            cropByItem.put(c.item, c);
            if (c.extraItem != null && !c.key.equals("WHEAT")) cropByItem.put(c.extraItem, c);
            for (String b : c.blocks) cropByBlock.put(b, c);
        }
        cropByBlock.put("carrots", cropByKey.get("CARROT"));
        cropByBlock.put("potatoes", cropByKey.get("POTATO"));
        for (Plot p : garden.plots) { plotById.put(p.id, p); plotAt[p.col][p.row] = p; }
        for (PlotGroup g : garden.plotGroups) groupById.put(g.id, g);
        for (Pest p : garden.pests.pests) pestById.put(p.id, p);
        for (Visitor v : visitors.visitors) visitorById.put(v.id, v);
        for (Mutation m : greenhouse.mutations) mutationById.put(m.id, m);
        for (GhCrop c : greenhouse.crops) ghCropByKey.put(c.crop, c);
    }

    public Crop crop(String key) { return cropByKey.get(key); }
    public Crop cropByItem(String itemId) { return cropByItem.get(itemId); }
    /** By lower-case vanilla block name ("wheat", "carrots", "sugar_cane", "rose_bush"). */
    public Crop cropByBlock(String block) { return cropByBlock.get(block); }
    public List<Crop> crops() { return garden.crops; }
    public Plot plot(String id) { return plotById.get(id); }
    public Plot plotAt(int col, int row) { return col < 0 || row < 0 || col > 4 || row > 4 ? null : plotAt[col][row]; }
    public List<Plot> plots() { return garden.plots; }
    public PlotGroup group(String id) { return groupById.get(id); }
    public Pest pest(String id) { return pestById.get(id); }
    public List<Pest> pests() { return garden.pests.pests; }
    public Visitor visitor(String id) { return visitorById.get(id); }
    public List<Visitor> allVisitors() { return visitors.visitors; }
    public Mutation mutation(String id) { return mutationById.get(id); }
    public GhCrop ghCrop(String key) { return ghCropByKey.get(key); }

    public GardenTables.Vacuum vacuum(String itemId) {
        for (Vacuum v : garden.pests.vacuums) if (v.id.equals(itemId)) return v;
        return null;
    }

    public Sprayer sprayer(String itemId) {
        for (Sprayer s : garden.pests.sprayers) if (s.id.equals(itemId)) return s;
        return null;
    }

    public Trap trap(String itemId) {
        for (Trap s : garden.pests.traps) if (s.id.equals(itemId)) return s;
        return null;
    }

    public CompUpgrade composterUpgrade(String id) {
        for (CompUpgrade u : garden.composter.upgrades) if (u.id.equals(id)) return u;
        return null;
    }

    public BarnSkin barnSkin(String id) {
        for (BarnSkin b : garden.barnSkins) if (b.id.equals(id)) return b;
        return null;
    }

    public RarityTune rarity(String r) {
        RarityTune t = visitors.rarities.get(r);
        return t != null ? t : visitors.rarities.get("UNCOMMON");
    }
}
